{
  "name": "液位传感器",
  "name_en": "Liquid Level Sensor",
  "manufacturer": "",
  "description": "用于检测容器、储液槽或流体处理系统中液体液位的实验室设备，可用于监测试剂余量、避免吸空或溢出，并支持自动化流体处理过程中的液位确认。",
  "description_en": "A laboratory device used to detect the liquid level in containers, reservoirs, or fluid-handling systems. It is used to monitor reagent volume, prevent running dry or overflow, and confirm liquid presence in automated fluid-handling workflows.",
  "tag_hints": [
    "liquid level sensing",
    "fluid handling",
    "reservoir monitoring",
    "reagent level detection",
    "automation safety"
  ],
  "actions": [
    {
      "action_name": "auto-open",
      "description": "打开设备连接。",
      "description_en": "Open the device connection."
    },
    {
      "action_name": "auto-close",
      "description": "关闭设备连接。",
      "description_en": "Close the device connection."
    },
    {
      "action_name": "auto-execute",
      "description": "执行设备命令。",
      "description_en": "Execute a device command."
    },
    {
      "action_name": "auto-getlevel",
      "description": "读取当前液位。",
      "description_en": "Read the current liquid level."
    },
    {
      "action_name": "auto-setdebug",
      "description": "设置调试输出。",
      "description_en": "Set debug output."
    }
  ]
}

